var n=`1322-cazuela-chilena`;var a=`world-1322`;var t=`CL`;var s=`south-america`;var r=4;var o=122;var l={en:`Cazuela Chilena`,ua:`Чилійська касуела`};var g={en:`Cazuela Chilena is a dish from Chile featuring beef shank, yellow onion, garlic, pumpkin. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Чилійська касуела, страва кухні країни Чилі з такими основними складниками: яловича гомілка, жовта цибуля, часник, гарбуз. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 85 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 85 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:85,i:[[`beef-shank`,810,`g`],[`water`,1650,`ml`],[`yellow-onion`,180,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`pumpkin`,350,`g`],[`potato`,350,`g`],[`carrot`,260,`g`],[`green-beans`,210,`g`],[`sweet-corn`,2,`pcs`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var m={slug:n,id:a,country:`CL`,region:s,servings:4,minutes:122,title:l,text:g,steps:h};export{t as country,m as default,a as id,o as minutes,s as region,r as servings,n as slug,h as steps,g as text,l as title};